import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry 
} from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { 
    imageUrl, 
    textContent: rawTextConfig, 
    cinematicPrimitives, 
    colors 
  } = config;

  const items = rawTextConfig ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(item => item.role === 'headline') || items[0];
  const headlineText = headlineItem?.text ?? '';

  const group = new ctx.THREE.Group();

  // --- Card plane background ---
  const planeGeo = new PlaneGeometry(2, 1.25); // matching atlas region aspect 512/320
  const planeMat = new MeshBasicNodeMaterial({
    color: colors?.surface || '#0b0b10',
    side: ctx.THREE.DoubleSide,
  });
  const planeMesh = new ctx.THREE.Mesh(planeGeo, planeMat);
  planeMesh.position.z = -0.05; // behind text
  group.add(planeMesh);

  // Asynchronously load card texture
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      // Apply only the atlas region (assumes atlas image contains the full region at 0,0)
      tex.repeat.set(1, 1);
      tex.offset.set(0, 0);
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // --- Text overlay ---
  if (headlineText) {
    const fontSize = headlineItem?.typography?.fontSize ?? 39;
    const textObj = ctx.fontAtlas.createText(headlineText, {
      fontSize,
      color: colors?.paper || '#e8ecf2',
      align: 'center',
    });
    textObj.position.z = 0.02; // slightly in front of plane
    textObj.scale.set(1, 1, 1);
    group.add(textObj);
  }

  // --- Cinematic primitive: parallax-scroll ---
  let parallaxResult = null;
  if (cinematicPrimitives?.length) {
    const configPrim = cinematicPrimitives.find(p => p.name === 'parallax-scroll');
    if (configPrim) {
      parallaxResult = ctx.primitives['parallax-scroll'](group, configPrim.params);
    }
  }

  // --- Interactive handlers ---
  const handlers = {};

  // Hover: rise-in (subtle 0.15 units)
  handlers.onPointerEnter = () => {
    gsap.to(planeMesh.position, {
      y: 0.15,
      duration: 0.5,
      ease: 'power2.out',
    });
  };
  handlers.onPointerLeave = () => {
    gsap.to(planeMesh.position, {
      y: 0,
      duration: 0.5,
      ease: 'power2.out',
    });
  };

  // Click: emit hub-journal.select
  handlers.onClick = () => {
    ctx.emit('hub-journal.select', { source: 'label-card' });
  };

  group.userData.handlers = handlers;

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Kill all gsap tweens on the group's children
    gsap.killTweensOf(planeMesh.position);
    gsap.killTweensOf(group.children);
    if (parallaxResult && parallaxResult.cleanup) {
      parallaxResult.cleanup();
    }
    // Dispose geometry and material
    planeGeo.dispose();
    planeMat.dispose();
  };

  return group;
}
